<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-alt: #f8fafc;
      --text: #0f172a;
      --muted: #475569;
      --border: #cbd5e1;
      --border-strong: #94a3b8;
      --accent: #2563eb;
      --accent-soft: #dbeafe;
      --shadow: 0 20px 45px -30px rgba(15, 23, 42, 0.35);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, #eef4ff 0, var(--bg) 45%, #edf2f7 100%);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      background: var(--surface);
      color: var(--text);
      border: 2px solid var(--accent);
      border-radius: 999px;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: none;
    }

    .page {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 4rem 1.25rem;
    }

    .card {
      width: min(100%, 640px);
      background: var(--surface);
      border: 1px solid rgba(148, 163, 184, 0.35);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: clamp(1.5rem, 3vw, 2.5rem);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
    }

    h1 {
      margin: 0;
      font-size: clamp(1.75rem, 3vw, 2.5rem);
      line-height: 1.15;
    }

    .intro {
      margin: 0.75rem 0 2rem;
      color: var(--muted);
      max-width: 42ch;
    }

    .form-field {
      margin: 0;
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      padding: 0;
      margin: 0 0 1rem;
      font-size: 1.05rem;
      font-weight: 600;
    }

    .options {
      display: grid;
      gap: 0.75rem;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .option {
      position: relative;
    }

    .option input {
      position: absolute;
      inset: 0;
      opacity: 0;
    }

    .option label {
      display: flex;
      align-items: center;
      gap: 0.875rem;
      padding: 1rem 1rem 1rem 1.1rem;
      border: 1.5px solid var(--border);
      border-radius: 16px;
      background: var(--surface-alt);
      color: var(--text);
      cursor: pointer;
      transition: border-color 0.2s ease, background-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
      min-width: 0;
    }

    .option label:hover {
      border-color: var(--border-strong);
      transform: translateY(-1px);
    }

    .option label::before {
      content: "";
      flex: 0 0 1.15rem;
      width: 1.15rem;
      height: 1.15rem;
      border: 2px solid var(--border-strong);
      border-radius: 50%;
      background: var(--surface);
      box-shadow: inset 0 0 0 0.3rem var(--surface);
      transition: border-color 0.2s ease, box-shadow 0.2s ease;
    }

    .option input:checked + label {
      border-color: var(--accent);
      background: var(--accent-soft);
    }

    .option input:checked + label::before {
      border-color: var(--accent);
      box-shadow: inset 0 0 0 0.35rem var(--accent);
    }

    .option input:focus-visible + label {
      outline: 3px solid var(--accent);
      outline-offset: 3px;
    }

    .actions {
      display: flex;
      justify-content: flex-start;
      margin-top: 1.5rem;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.4rem;
      background: linear-gradient(135deg, #2563eb, #1d4ed8);
      color: #fff;
      font: inherit;
      font-weight: 700;
      box-shadow: 0 14px 28px -18px rgba(37, 99, 235, 0.75);
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
    }

    button:hover {
      transform: translateY(-1px);
      filter: brightness(1.02);
    }

    button:focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 3px;
    }

    .status {
      margin-top: 1rem;
      min-height: 1.5rem;
      color: var(--muted);
    }

    @media (max-width: 480px) {
      .page {
        padding: 3.5rem 0.9rem;
      }

      .card {
        border-radius: 16px;
      }

      .option label {
        padding-inline: 0.9rem;
      }
    }

    @media (forced-colors: active) {
      .skip-link,
      .card,
      .option label,
      button {
        border: 1px solid ButtonBorder;
        background: Canvas;
        color: CanvasText;
      }

      .skip-link:focus,
      .option input:focus-visible + label,
      button:focus-visible {
        outline: 2px solid Highlight;
        outline-offset: 2px;
      }

      .option input:checked + label::before {
        box-shadow: inset 0 0 0 0.35rem Highlight;
        border-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main" class="page">
    <section class="card" aria-labelledby="notifications-heading">
      <p class="eyebrow">Preferences</p>
      <h1 id="notifications-heading">Choose your notification channel</h1>
      <p class="intro">Select one option so we can tailor updates to the way you like to hear from us.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset>
            <legend>How do you prefer to receive notifications?</legend>
            <ul class="options" role="list">
              <li class="option">
                <input type="radio" id="notify-email" name="notification-preference" value="Email" required />
                <label for="notify-email">Email</label>
              </li>
              <li class="option">
                <input type="radio" id="notify-sms" name="notification-preference" value="SMS" />
                <label for="notify-sms">SMS</label>
              </li>
              <li class="option">
                <input type="radio" id="notify-push" name="notification-preference" value="Push Notifications" />
                <label for="notify-push">Push Notifications</label>
              </li>
            </ul>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit</button>
        </div>

        <p class="status" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('notification-form');
    const status = document.getElementById('form-status');

    form.addEventListener('submit', (event) => {
      const choice = form.querySelector('input[name="notification-preference"]:checked');

      if (!choice) {
        status.textContent = 'Please choose one notification option before submitting.';
        return;
      }

      event.preventDefault();
      status.textContent = `Saved preference: ${choice.value}.`;
    });
  </script>
</body>
</html>
